  static values = { scopeSelector: { type: String, default: "body" } }

  connect() {
    super.connect()

    if (this.element.closest(this.scopeSelectorValue)) {
      this.notifyBridgeOfConnect()
      this.#observeStamp()
    }
  }

  disconnect() {
    super.disconnect()
    this.notifyBridgeOfDisconnect()
    this.stampObserver?.disconnect()
  }

  notifyBridgeOfConnect() {
    const bridgeElement = this.bridgeElement

    this.send("connect", {
      title: bridgeElement.title,
      description: this.element.querySelector("[data-bridge-description-time]")?.textContent || bridgeElement.bridgeAttribute("description")
    })
  }

  notifyBridgeOfDisconnect() {
    this.send("disconnect")
  }

  #observeStamp() {
    this.stampObserver = new MutationObserver(() => {
      this.notifyBridgeOfConnect()
    })

    this.stampObserver.observe(this.element, {
      attributes: true,
      childList: true,
      subtree: true
    })
  }
}
module ApplicationHelper
  def page_title_tag
    account_name = if Current.account && Current.session&.identity&.users&.many?
      Current.account&.name
    end
    tag.title [ @page_title, account_name, "Fizzy" ].compact.join(" | ")
  end

  def icon_tag(name, **options)
    tag.span class: class_names("icon icon--#{name}", options.delete(:class)), "aria-hidden": true, **options
  end

  def local_time_tag(timestamp, format:, data: {})
    raw_timestamp = timestamp.utc.iso8601(6)
    tag.time raw_timestamp, datetime: raw_timestamp, data: {
      controller: "local-time",
      local_time_format_value: format.to_s
    }.merge(data)
  end

  def back_link_to(label, url, action, prefer_referrer: [], **options)
    data = { controller: "hotkey", action: action }
    if prefer_referrer.any?
      data[:turbo_navigation_target] = "referrerBackLink"
      data[:turbo_navigation_allowed_referrer_paths] = prefer_referrer.join(",")
    end
    link_to url, class: "btn btn--back btn--circle-mobile", data: data, **options do
      icon_tag("arrow-left") + tag.strong("Back to #{label}", class: "overflow-ellipsis") + tag.kbd("ESC", class: "txt-x-small hide-on-touch").html_safe
    end
  end
end

